arguments.file_text:
:root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --surface-2: #f2efe9;
  --ink: #14110f;
  --ink-2: #3d3a35;
  --muted: #76706a;
  --line: #e6e1d8;
  --accent: #2a4a3a;
  --accent-ink: #f5f1ea;
  --sale: #b04332;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(20, 17, 15, 0.04),
    0 2px 8px rgba(20, 17, 15, 0.04);
  --shadow-md: 0 6px 24px rgba(20, 17, 15, 0.08);
  --container: 1200px;
  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-serif: "Fraunces", "Times New Roman", Georgia, serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
}

a {
  color: inherit;
}

/* Accessibility utilities */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: var(--accent-ink);
  padding: 12px 16px;
  border-radius: 0 0 8px 0;
  z-index: 100;
  font-weight: 600;
}
.skip-link:focus {
  left: 0;
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* Layout */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* Announcement bar */
.announce {
  background: var(--ink);
  color: var(--accent-ink);
  font-size: 13px;
  text-align: center;
  padding: 10px 16px;
  letter-spacing: 0.02em;
}
.announce strong {
  font-weight: 600;
}
.announce a {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 248, 245, 0.92);
  backdrop-filter: saturate(160%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  padding: 18px 24px;
  max-width: var(--container);
  margin: 0 auto;
}
.brand {
  font-family: var(--font-serif);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  display: inline-block;
  width: 10px;
  height: 10px;
  background: var(--accent);
  border-radius: 50%;
  margin-right: 8px;
  vertical-align: 1px;
}
.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 28px;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  position: relative;
}
.primary-nav a:hover {
  color: var(--ink);
}
.primary-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--ink);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}
.primary-nav a:hover::after {
  transform: scaleX(1);
}
.header-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink);
  padding: 8px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  position: relative;
  transition: background 0.2s;
}
.icon-btn:hover {
  background: var(--surface-2);
}
.icon-btn .badge {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--sale);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}

/* Hero */
.hero {
  padding: 56px 0 72px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 48px;
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  background: rgba(42, 74, 58, 0.08);
  padding: 8px 14px;
  border-radius: 999px;
  margin-bottom: 24px;
}
.hero h1 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(40px, 6vw, 76px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 0 0 20px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
}
.hero p.lede {
  font-size: 18px;
  color: var(--ink-2);
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  font-size: 15px;
  text-decoration: none;
  transition: transform 0.15s ease, background 0.2s ease, color 0.2s ease,
    border-color 0.2s ease;
}
.btn:active {
  transform: translateY(1px);
}
.btn-primary {
  background: var(--ink);
  color: var(--accent-ink);
}
.btn-primary:hover {
  background: var(--accent);
}
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-ghost:hover {
  background: var(--ink);
  color: var(--accent-ink);
}
.hero-meta {
  margin-top: 36px;
  display: flex;
  gap: 32px;
  flex-wrap: wrap;
  color: var(--muted);
  font-size: 13px;
}
.hero-meta strong {
  color: var(--ink);
  font-weight: 600;
  font-size: 22px;
  font-family: var(--font-serif);
  display: block;
  margin-bottom: 2px;
}

.hero-visual {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  background: linear-gradient(135deg, #d9c9b3 0%, #a98e6c 100%);
}
.hero-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(60% 60% at 30% 30%, rgba(255, 255, 255, 0.35), transparent 60%),
    radial-gradient(40% 50% at 80% 80%, rgba(20, 17, 15, 0.25), transparent 70%);
  mix-blend-mode: soft-light;
}
.hero-visual svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.hero-tag {
  position: absolute;
  bottom: 20px;
  left: 20px;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 2;
  box-shadow: var(--shadow-sm);
}
.hero-tag-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}

/* Marquee strip */
.marquee {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  overflow: hidden;
}
.marquee-track {
  display: flex;
  gap: 56px;
  padding: 18px 0;
  white-space: nowrap;
  animation: marquee 36s linear infinite;
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 18px;
  color: var(--ink-2);
}
.marquee-track span {
  display: inline-flex;
  align-items: center;
  gap: 56px;
}
.marquee-track span::before {
  content: "✦";
  color: var(--accent);
  font-style: normal;
}
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@media (prefers-reduced-motion: reduce) {
  .marquee-track { animation: none; }
}

/* Section */
section {
  padding: 80px 0;
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-eyebrow {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  margin: 0 0 8px;
}
.section-head h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(30px, 4vw, 44px);
  line-height: 1.05;
  letter-spacing: -0.015em;
  margin: 0;
  max-width: 22ch;
}
.section-head p {
  margin: 0;
  color: var(--muted);
  max-width: 42ch;
}
.section-link {
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  color: var(--ink);
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* Filters */
.filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.chip {
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink-2);
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  transition: all 0.2s;
}
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip[aria-pressed="true"] {
  background: var(--ink);
  color: var(--accent-ink);
  border-color: var(--ink);
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px 24px;
}
.product-card {
  display: flex;
  flex-direction: column;
  gap: 14px;
  text-decoration: none;
  color: inherit;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-2);
  transition: transform 0.4s ease;
}
.product-media svg {
  width: 100%;
  height: 100%;
}
.product-card:hover .product-media {
  transform: translateY(-4px);
}
.product-flag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--surface);
  color: var(--ink);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 6px 10px;
  border-radius: 999px;
  box-shadow: var(--shadow-sm);
}
.product-flag.sale { background: var(--sale); color: #fff; }
.product-flag.new  { background: var(--accent); color: var(--accent-ink); }

.wishlist-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--surface);
  border: none;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, background 0.2s;
}
.wishlist-btn:hover { transform: scale(1.08); }
.wishlist-btn[aria-pressed="true"] { background: var(--ink); color: #fff; }
.wishlist-btn[aria-pressed="true"] svg { fill: currentColor; }

.product-quick {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: var(--accent-ink);
  border: none;
  padding: 10px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.product-card:hover .product-quick,
.product-card:focus-within .product-quick {
  opacity: 1;
  transform: translateY(0);
}

.product-info { display: grid; gap: 4px; }
.product-cat {
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.product-name {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.005em;
  margin: 0;
}
.product-price {
  display: flex;
  gap: 10px;
  align-items: baseline;
  font-size: 15px;
}
.price-now { font-weight: 600; }
.price-was { color: var(--muted); text-decoration: line-through; font-size: 13px; }
.price-save { color: var(--sale); font-size: 12px; font-weight: 600; }

.product-swatches {
  display: flex;
  gap: 6px;
  margin-top: 4px;
}
.swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid var(--line);
  display: inline-block;
}

/* Deals */
.deals {
  background: var(--ink);
  color: var(--accent-ink);
}
.deals .section-eyebrow { color: #d4b88f; }
.deals .section-head h2 { color: var(--accent-ink); }
.deals .section-head p { color: rgba(245, 241, 234, 0.7); }
.deals .section-link { color: var(--accent-ink); border-color: var(--accent-ink); }
.deals .section-link:hover { color: #d4b88f; border-color: #d4b88f; }

.countdown {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 16px;
}
.countdown-label {
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(245, 241, 234, 0.6);
}
.countdown-units {
  display: flex;
  gap: 6px;
}
.countdown-unit {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  padding: 6px 10px;
  min-width: 52px;
  text-align: center;
}
.countdown-num {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 500;
  display: block;
  line-height: 1;
}
.countdown-cap {
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(245, 241, 234, 0.6);
}

.deal-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  min-height: 520px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: 28px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
  transition: transform 0.3s ease;
  min-height: 220px;
}
.deal-card:hover { transform: translateY(-4px); }
.deal-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--bg-grad, linear-gradient(135deg, #2a4a3a, #14110f));
}
.deal-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(180deg, transparent 30%, rgba(20, 17, 15, 0.55) 100%);
}
.deal-card svg.deal-art {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  opacity: 0.45;
}
.deal-large { grid-row: span 2; }
.deal-pct {
  font-family: var(--font-serif);
  font-size: 56px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.02em;
}
.deal-large .deal-pct { font-size: 96px; }
.deal-card h3 {
  font-family: var(--font-serif);
  font-size: 24px;
  font-weight: 500;
  margin: 8px 0 4px;
}
.deal-large h3 { font-size: 36px; }
.deal-card p { margin: 0 0 16px; color: rgba(255, 255, 255, 0.85); font-size: 14px; }
.deal-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  align-self: flex-start;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
  width: fit-content;
}

/* Categories */
.cats {
  background: var(--surface-2);
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.cat-card {
  position: relative;
  aspect-ratio: 1 / 1.1;
  border-radius: var(--radius-lg);
  overflow: hidden;
  text-decoration: none;
  color: var(--ink);
  background: var(--surface);
  transition: transform 0.3s;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 20px;
}
.cat-card:hover { transform: translateY(-4px); }
.cat-card svg {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
}
.cat-meta { position: relative; z-index: 1; }
.cat-card h3 {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 500;
  margin: 0;
}
.cat-count {
  font-size: 13px;
  color: var(--muted);
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr;
  gap: 24px;
}
.story {
  background: var(--surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  transition: transform 0.3s, box-shadow 0.3s;
}
.story:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.story-media {
  aspect-ratio: 16 / 10;
  background: var(--surface-2);
  position: relative;
}
.story-media svg { width: 100%; height: 100%; display: block; }
.story-body { padding: 22px 24px 26px; }
.story-tag {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin: 0 0 8px;
}
.story h3 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: 22px;
  letter-spacing: -0.005em;
  margin: 0 0 8px;
  line-height: 1.2;
}
.story-meta {
  font-size: 13px;
  color: var(--muted);
  margin-top: 14px;
  display: flex;
  gap: 12px;
}
.story-feature .story-media { aspect-ratio: 4 / 5; }
.story-feature h3 { font-size: 28px; }

/* Testimonials */
.testimonials {
  background: var(--surface-2);
  text-align: center;
}
.testimonial-stack {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: left;
}
.testimonial {
  background: var(--surface);
  padding: 28px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
}
.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: 19px;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: -0.005em;
  margin: 0 0 18px;
  quotes: """ """;
}
.testimonial blockquote::before { content: open-quote; }
.testimonial blockquote::after { content: close-quote; }
.t-author {
  display: flex;
  align-items: center;
  gap: 12px;
}
.t-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 14px;
}
.t-name { font-weight: 600; font-size: 14px; }
.t-handle { font-size: 12px; color: var(--muted); }
.t-stars { color: #d4882b; letter-spacing: 2px; margin-bottom: 8px; font-size: 13px; }

/* Newsletter */
.newsletter {
  background: var(--ink);
  color: var(--accent-ink);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 40px;
  align-items: center;
  position: relative;
  overflow: hidden;
  margin: 0 24px;
}
.newsletter::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -120px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 184, 143, 0.4), transparent 70%);
  pointer-events: none;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.015em;
  margin: 0 0 12px;
}
.newsletter p { margin: 0; color: rgba(245, 241, 234, 0.75); }
.newsletter form {
  display: flex;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 6px;
}
.newsletter form:focus-within {
  border-color: rgba(255, 255, 255, 0.4);
}
.newsletter input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--accent-ink);
  font: inherit;
  padding: 12px 16px;
  outline: none;
  min-width: 0;
}
.newsletter input::placeholder { color: rgba(245, 241, 234, 0.55); }
.newsletter button {
  background: var(--accent-ink);
  color: var(--ink);
  border: none;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  white-space: nowrap;
}
.newsletter button:hover { background: #d4b88f; }
.newsletter .form-note {
  font-size: 12px;
  color: rgba(245, 241, 234, 0.6);
  margin-top: 10px;
}
.newsletter-success {
  margin-top: 12px;
  font-size: 14px;
  color: #d4b88f;
}

/* Footer */
.site-footer {
  padding: 80px 0 32px;
  background: var(--bg);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--line);
}
.site-footer h4 {
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 16px;
  font-weight: 600;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { text-decoration: none; font-size: 14px; color: var(--ink-2); }
.site-footer a:hover { color: var(--ink); }
.footer-brand p { color: var(--muted); font-size: 14px; max-width: 38ch; }
.social-row { display: flex; gap: 10px; margin-top: 16px; }
.social-row a {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
  transition: all 0.2s;
}
.social-row a:hover { background: var(--ink); color: var(--accent-ink); border-color: var(--ink); }
.footer-bottom {
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: var(--muted);
}
.footer-bottom ul { display: flex; gap: 20px; list-style: none; padding: 0; margin: 0; }

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--accent-ink);
  padding: 14px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.toast-dot {
  width: 8px; height: 8px; border-radius: 50%; background: #7ec48f;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-stack { grid-template-columns: 1fr 1fr; }
  .deal-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-large { grid-column: span 2; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { max-width: 520px; }
}
@media (max-width: 720px) {
  section { padding: 56px 0; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 20px 14px; }
  .cat-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .testimonial-stack { grid-template-columns: 1fr; }
  .deal-grid { grid-template-columns: 1fr; }
  .deal-large { grid-column: auto; }
  .newsletter { grid-template-columns: 1fr; padding: 36px 24px; margin: 0 16px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-meta { gap: 20px; }
  .container { padding: 0 16px; }
}

