          </form>
          <p id="news-status" className="form-note" role="status">
            {status === "ok" && <span className="newsletter-success">✓ Thank you — please check your inbox to confirm.</span>}
            {status === "error" && <span style={{ color: "#f0a394" }}>Please enter a valid email address.</span>}
            {status === "idle" && "We'll never share your email. Read our privacy promise."}
          </p>
        </div>
      </div>
    </section>
  );
}

function Footer() {
  return (
    <footer id="about" className="site-footer">
      <div className="container">
        <div className="footer-grid">
          <div className="footer-brand">
            <a href="#" className="brand" aria-label="Maren and Co. home">
              <span className="brand-mark" aria-hidden="true"></span>Maren &amp; Co.
            </a>
            <p style={{ marginTop: 16 }}>
              A small studio making considered goods in Portland, Oregon. We design slowly,
              make in small batches, and stand behind every piece for life.
            </p>
            <div className="social-row">
              <a href="#" aria-label="Maren and Co. on Instagram"><Icon name="instagram" size={16} /></a>
              <a href="#" aria-label="Maren and Co. on Twitter"><Icon name="twitter" size={16} /></a>
              <a href="#" aria-label="Maren and Co. on Pinterest"><Icon name="pinterest" size={16} /></a>
            </div>
          </div>
          <div>
            <h4>Shop</h4>
            <ul>
              <li><a href="#">New In</a></li>
              <li><a href="#">Apparel</a></li>
              <li><a href="#">Home &amp; Living</a></li>
              <li><a href="#">Sale</a></li>
              <li><a href="#">Gift cards</a></li>
            </ul>
          </div>
          <div>
            <h4>Company</h4>
            <ul>
              <li><a href="#">Our story</a></li>
              <li><a href="#">Materials</a></li>
              <li><a href="#">Sustainability</a></li>
              <li><a href="#">Journal</a></li>
              <li><a href="#">Careers</a></li>
            </ul>
          </div>
          <div>
            <h4>Help</h4>
            <ul>
              <li><a href="#">Shipping &amp; returns</a></li>
              <li><a href="#">Size guide</a></li>
              <li><a href="#">Care &amp; repair</a></li>
              <li><a href="#">Contact us</a></li>
              <li><a href="#">Track your order</a></li>
            </ul>
          </div>
        </div>
        <div className="footer-bottom">
          <span>© 2026 Maren &amp; Co. All rights reserved.</span>
          <ul>
            <li><a href="#">Privacy</a></li>
            <li><a href="#">Terms</a></li>
            <li><a href="#">Accessibility</a></li>
            <li><a href="#">Cookies</a></li>
          </ul>
        </div>
      </div>
    </footer>
  );
}

function Toast({ message, show }) {
  return (
    <div className={`toast${show ? " show" : ""}`} role="status" aria-live="polite">
      <span className="toast-dot" aria-hidden="true"></span>
      {message}
    </div>
  );
}

/* ---------- App ---------- */
function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toast, setToast] = useState({ msg: "", show: false });
  const toastTimer = useRef(null);

  const showToast = (msg) => {
    setToast({ msg, show: true });
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(t => ({ ...t, show: false })), 2400);
  };

  const handleAdd = (p) => {
    setCart(c => [...c, p.id]);
    showToast(`Added “${p.name}” to your bag`);
  };
  const handleWish = (id) => {
    setWishlist(w => {
      const has = w.includes(id);
      showToast(has ? "Removed from wishlist" : "Saved to wishlist");
      return has ? w.filter(x => x !== id) : [...w, id];
    });
  };
  const handleSearch = () => showToast("Search is coming soon");

  return (
    <>
      <Announcement />
      <Header cartCount={cart.length} wishCount={wishlist.length} onSearch={handleSearch} />
      <main id="main">
        <Hero />
        <Marquee />
        <FeaturedProducts wishlist={wishlist} onWish={handleWish} onAdd={handleAdd} />
        <Deals />
        <Categories />
        <Editorial />
        <Testimonials />
        <Newsletter />
      </main>
      <Footer />
      <Toast message={toast.msg} show={toast.show} />
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
