      </div>
    </div>
  );
}

function ProductCard({ product, isWished, onWish, onAdd }) {
  return (
    <article className="product-card">
      <div className="product-media">
        <Artwork id={`p-${product.id}`} palette={product.palette} shape={product.shape} />
        {product.flag && (
          <span className={`product-flag ${product.flag}`}>
            {product.flag === "sale" ? "Sale" : "New"}
          </span>
        )}
        <button
          className="wishlist-btn"
          aria-label={isWished ? `Remove ${product.name} from wishlist` : `Add ${product.name} to wishlist`}
          aria-pressed={isWished}
          onClick={() => onWish(product.id)}
        >
          <Icon name="heart" size={16} />
        </button>
        <button
          className="product-quick"
          onClick={() => onAdd(product)}
          aria-label={`Add ${product.name} to bag`}
