      </div>
      <div className="product-info">
        <span className="product-cat">{product.cat}</span>
        <h3 className="product-name">{product.name}</h3>
        <div className="product-price">
          <span className="price-now">${product.price}</span>
          {product.was && <><span className="price-was">${product.was}</span>
            <span className="price-save">Save ${product.was - product.price}</span></>}
        </div>
        <ul className="product-swatches" aria-label={`Available colors for ${product.name}`}>
          {product.colors.map((c, i) => (
            <li key={i} className="swatch" style={{ background: c }} aria-label={`Color option ${i + 1}`} />
          ))}
