function FeaturedProducts({ wishlist, onWish, onAdd }) {
  const [filter, setFilter] = useState("all");
  const filtered = useMemo(() => {
    if (filter === "all") return PRODUCTS;
    if (filter === "new") return PRODUCTS.filter(p => p.flag === "new");
    if (filter === "sale") return PRODUCTS.filter(p => p.flag === "sale");
    return PRODUCTS.filter(p => p.filter === filter);
  }, [filter]);

  return (
    <section id="featured" aria-labelledby="featured-title">
      <div className="container">
        <div className="section-head">
          <div>
            <p className="section-eyebrow">Featured products</p>
            <h2 id="featured-title">New favorites, fresh in this week</h2>
          </div>
          <a href="#" className="section-link">View all 248 products →</a>
        </div>
        <div className="filters" role="tablist" aria-label="Filter products">
          {FILTERS.map(f => (
            <button
              key={f.id}
              className="chip"
              role="tab"
              aria-selected={filter === f.id}
              aria-pressed={filter === f.id}
              onClick={() => setFilter(f.id)}
            >
              {f.label}
            </button>
          ))}
        </div>
        <div className="product-grid" role="list">
          {filtered.map(p => (
            <div role="listitem" key={p.id}>
              <ProductCard
                product={p}
                isWished={wishlist.includes(p.id)}
                onWish={onWish}
                onAdd={onAdd}
              />
            </div>
          ))}
          {filtered.length === 0 && (
            <p style={{ gridColumn: "1 / -1", color: "var(--muted)" }}>No products match this filter.</p>
          )}
        </div>
      </div>
    </section>
  );
}

function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 47 + 1000 * 60 * 23, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const ms = Math.max(0, target - now);
  const h = String(Math.floor(ms / 3600000)).padStart(2, "0");
  const m = String(Math.floor((ms % 3600000) / 60000)).padStart(2, "0");
  const s = String(Math.floor((ms % 60000) / 1000)).padStart(2, "0");
  return (
    <div className="countdown" aria-live="polite">
      <span className="countdown-label">Sale ends in</span>
      <div className="countdown-units">
        <div className="countdown-unit"><span className="countdown-num">{h}</span><span className="countdown-cap">Hrs</span></div>
        <div className="countdown-unit"><span className="countdown-num">{m}</span><span className="countdown-cap">Min</span></div>
        <div className="countdown-unit"><span className="countdown-num">{s}</span><span className="countdown-cap">Sec</span></div>
      </div>
    </div>
  );
}

function Deals() {
  return (
    <section id="deals" className="deals" aria-labelledby="deals-title">
      <div className="container">
