      <span className="toast-dot" aria-hidden="true"></span>
      {message}
    </div>
  );
}

/* ---------- App ---------- */
function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toast, setToast] = useState({ msg: "", show: false });
  const toastTimer = useRef(null);

  const showToast = (msg) => {
    setToast({ msg, show: true });
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(t => ({ ...t, show: false })), 2400);
  };

  const handleAdd = (p) => {
    setCart(c => [...c, p.id]);
    showToast(`Added “${p.name}” to your bag`);
  };
  const handleWish = (id) => {
    setWishlist(w => {
      const has = w.includes(id);
      showToast(has ? "Removed from wishlist" : "Saved to wishlist");
      return has ? w.filter(x => x !== id) : [...w, id];
    });
  };
  const handleSearch = () => showToast("Search is coming soon");

  return (
    <>
      <Announcement />
      <Header cartCount={cart.length} wishCount={wishlist.length} onSearch={handleSearch} />
      <main id="main">
        <Hero />
        <Marquee />
        <FeaturedProducts wishlist={wishlist} onWish={handleWish} onAdd={handleAdd} />
        <Deals />
        <Categories />
        <Editorial />
        <Testimonials />
        <Newsletter />
      </main>
      <Footer />
      <Toast message={toast.msg} show={toast.show} />
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

