/* ---------- Generated SVG artwork (no external images, fully accessible) ---------- */
const Artwork = ({ id, palette, shape = "blob" }) => {
  const [a, b, c] = palette;
  const gid = `g-${id}`;
  return (
    <svg viewBox="0 0 400 500" preserveAspectRatio="xMidYMid slice" role="presentation">
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={a} />
          <stop offset="100%" stopColor={b} />
        </linearGradient>
      </defs>
      <rect width="400" height="500" fill={`url(#${gid})`} />
      {shape === "blob" && (
        <>
          <circle cx="120" cy="180" r="120" fill={c} opacity="0.55" />
          <circle cx="290" cy="340" r="90" fill="#fff" opacity="0.18" />
        </>
      )}
      {shape === "stripes" && (
        <>
          <rect x="40" y="0" width="60" height="500" fill={c} opacity="0.6" />
          <rect x="240" y="0" width="20" height="500" fill="#fff" opacity="0.3" />
        </>
      )}
      {shape === "circle" && (
        <>
          <circle cx="200" cy="250" r="150" fill={c} opacity="0.7" />
          <circle cx="200" cy="250" r="80" fill="#fff" opacity="0.25" />
        </>
      )}
      {shape === "arch" && (
        <>
          <path d="M80 500 V260 a120 120 0 0 1 240 0 V500 Z" fill={c} opacity="0.7" />
          <circle cx="200" cy="200" r="40" fill="#fff" opacity="0.4" />
        </>
      )}
      {shape === "wave" && (
        <>
          <path d="M0 320 C 100 260 200 380 400 300 V500 H0 Z" fill={c} opacity="0.7" />
          <circle cx="310" cy="140" r="60" fill="#fff" opacity="0.35" />
        </>
      )}
    </svg>
  );
};

