function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("idle");
  const submit = (e) => {
    e.preventDefault();
    if (!email.includes("@")) {
      setStatus("error");
      return;
    }
    setStatus("ok");
    setEmail("");
  };
  return (
    <section aria-labelledby="news-title" style={{ padding: "0 0 80px" }}>
      <div className="newsletter">
        <div>
          <h2 id="news-title">Letters from the studio</h2>
