function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 47 + 1000 * 60 * 23, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const ms = Math.max(0, target - now);
  const h = String(Math.floor(ms / 3600000)).padStart(2, "0");
  const m = String(Math.floor((ms % 3600000) / 60000)).padStart(2, "0");
  const s = String(Math.floor((ms % 60000) / 1000)).padStart(2, "0");
  return (
    <div className="countdown" aria-live="polite">
      <span className="countdown-label">Sale ends in</span>
      <div className="countdown-units">
        <div className="countdown-unit"><span className="countdown-num">{h}</span><span className="countdown-cap">Hrs</span></div>
        <div className="countdown-unit"><span className="countdown-num">{m}</span><span className="countdown-cap">Min</span></div>
        <div className="countdown-unit"><span className="countdown-num">{s}</span><span className="countdown-cap">Sec</span></div>
      </div>
    </div>
  );
}

