  position: relative;
  overflow: hidden;
  margin: 0 24px;
}
.newsletter::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -120px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 184, 143, 0.4), transparent 70%);
  pointer-events: none;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.015em;
  margin: 0 0 12px;
}
.newsletter p { margin: 0; color: rgba(245, 241, 234, 0.75); }
.newsletter form {
  display: flex;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 6px;
}
.newsletter form:focus-within {
