  overflow: hidden;
  margin: 0 24px;
}
.newsletter::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -120px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212, 184, 143, 0.4), transparent 70%);
  pointer-events: none;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 40px);
  line-height: 1.1;
  letter-spacing: -0.015em;
  margin: 0 0 12px;
}
.newsletter p { margin: 0; color: rgba(245, 241, 234, 0.75); }
.newsletter form {
  display: flex;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 6px;
}
.newsletter form:focus-within {
  border-color: rgba(255, 255, 255, 0.4);
}
.newsletter input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--accent-ink);
  font: inherit;
  padding: 12px 16px;
  outline: none;
  min-width: 0;
}
.newsletter input::placeholder { color: rgba(245, 241, 234, 0.55); }
.newsletter button {
  background: var(--accent-ink);
  color: var(--ink);
  border: none;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  white-space: nowrap;
}
.newsletter button:hover { background: #d4b88f; }
.newsletter .form-note {
  font-size: 12px;
  color: rgba(245, 241, 234, 0.6);
  margin-top: 10px;
}
.newsletter-success {
  margin-top: 12px;
  font-size: 14px;
  color: #d4b88f;
}

/* Footer */
.site-footer {
  padding: 80px 0 32px;
  background: var(--bg);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--line);
}
.site-footer h4 {
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 16px;
  font-weight: 600;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { text-decoration: none; font-size: 14px; color: var(--ink-2); }
.site-footer a:hover { color: var(--ink); }
.footer-brand p { color: var(--muted); font-size: 14px; max-width: 38ch; }
.social-row { display: flex; gap: 10px; margin-top: 16px; }
.social-row a {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
  transition: all 0.2s;
}
.social-row a:hover { background: var(--ink); color: var(--accent-ink); border-color: var(--ink); }
.footer-bottom {
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: var(--muted);
}
.footer-bottom ul { display: flex; gap: 20px; list-style: none; padding: 0; margin: 0; }

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--accent-ink);
  padding: 14px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.toast-dot {
  width: 8px; height: 8px; border-radius: 50%; background: #7ec48f;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .testimonial-stack { grid-template-columns: 1fr 1fr; }
  .deal-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-large { grid-column: span 2; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { max-width: 520px; }
}
@media (max-width: 720px) {
  section { padding: 56px 0; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .primary-nav { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 20px 14px; }
  .cat-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .testimonial-stack { grid-template-columns: 1fr; }
  .deal-grid { grid-template-columns: 1fr; }
  .deal-large { grid-column: auto; }
  .newsletter { grid-template-columns: 1fr; padding: 36px 24px; margin: 0 16px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-meta { gap: 20px; }
  .container { padding: 0 16px; }
}
